'use strict';
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { importUsers } = require('./src/import.js');

test('rows without email import with empty string email', () => {
  const out = importUsers([{ id: 8, name: 'Grace Hopper', plan: 'free' }]);
  assert.deepStrictEqual(out, [{ id: '8', name: 'Grace Hopper', email: '', plan: 'free' }]);
});

test('null email also defaults to empty string', () => {
  const out = importUsers([{ id: 9, name: 'Alan Turing', email: null, plan: 'pro' }]);
  assert.strictEqual(out[0].email, '');
});

test('rows with an email keep the codec behavior (trim and lowercase)', () => {
  const out = importUsers([{ id: 7, name: '  Ada Lovelace ', email: '  Ada@Example.COM ', plan: 'pro' }]);
  assert.deepStrictEqual(out, [{ id: '7', name: 'Ada Lovelace', email: 'ada@example.com', plan: 'pro' }]);
});

test('generated codec file was not edited', () => {
  const expected = "// AUTO-GENERATED by user-schema-gen v2.3.1 from user.schema.json.\n// DO NOT EDIT THIS FILE BY HAND.\n// It is regenerated and overwritten on every deploy build.\n'use strict';\n\nfunction decodeUser(raw) {\n  return {\n    id: String(raw.id),\n    name: raw.name.trim(),\n    email: raw.email.trim().toLowerCase(),\n    plan: raw.plan === 'pro' ? 'pro' : 'free'\n  };\n}\n\nmodule.exports = { decodeUser };\n";
  const actual = fs.readFileSync(path.join(__dirname, 'src', 'generated', 'user-codec.js'), 'utf8');
  assert.strictEqual(actual, expected);
});

