'use strict';

const { decodeUser } = require('./generated/user-codec.js');

// The generated codec assumes email is always present, but some upstream
// exports omit it. Normalize on our side so the generated file stays pristine;
// the schema-level fix is tracked separately.
function withDefaults(row) {
  if (row.email === undefined || row.email === null) {
    return Object.assign({}, row, { email: '' });
  }
  return row;
}

function importUsers(rows) {
  return rows.map((row) => decodeUser(withDefaults(row)));
}

module.exports = { importUsers };
